 "content": "from functools import lru_cache

# Tile connected 8-cells into 2x2 blocks (color 1) and L triominoes.
# The L color identifies its missing corner: TL=2, BL=3, TR=4, BR=5.
MISSING_TO_COLOR = {"TL": 2, "BL": 3, "TR": 4, "BR": 5}


def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    if not cells:
        return [row[:] for row in grid]

    # Build possible placements indexed by their covered cell sets.
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
            if square <= cells:
                placements.append((square, 1))
            corners = {
                "TL": ((r, c + 1), (r + 1, c), (r + 1, c + 1)),
                "TR": ((r, c), (r + 1, c), (r + 1, c + 1)),
                "BL": ((r, c), (r, c + 1), (r + 1, c + 1)),
                "BR": ((r, c), (r, c + 1), (r + 1, c)),
            }
            for missing, pts in corners.items():
                shape = frozenset(pts)
                if shape <= cells:
                    placements.append((shape, MISSING_TO_COLOR[missing]))

    by_cell = {p: [] for p in cells}
    for shape, color in placements:
        for p in shape:
            by_cell[p].append((shape, color))

    @lru_cache(None)
    def solve(remaining):
        rem = frozenset(remaining)
        if not rem:
            return ()
        # Most constrained uncovered cell first.
        p = min(rem, key=lambda q: sum(shape <= rem for shape, _ in by_cell[q]))
        options = [(shape, color) for shape, color in by_cell[p] if shape <= rem]
        # Prefer square pieces, then consistent row-major orientation ordering.
        options.sort(key=lambda x: (x[1] != 1, x[1], tuple(sorted(x[0]))))
        for shape, color in options:
            rest = solve(frozenset(rem - shape))
            if rest is not None:
                return ((shape, color),) + rest
        return None

    tiling = solve(frozenset(cells))
    if tiling is None:
        raise ValueError("8-cells cannot be tiled by 2x2 squares and L triominoes")
    out = [row[:] for row in grid]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
